func TestParsePowerShellStyleOptions(t *testing.T) {
	opt, err := Parse([]string{"doctor", "-Pack", "_template", "-Target", "."})
	if err != nil {
		t.Fatal(err)
	}
	if opt.Command != "doctor" {
		t.Fatalf("Command = %q, want doctor", opt.Command)
	}
	if opt.Pack != "_template" || !opt.PackProvided {
		t.Fatalf("Pack = %q PackProvided=%t, want explicit _template", opt.Pack, opt.PackProvided)
	}
	if opt.Target != "." {
		t.Fatalf("Target = %q, want .", opt.Target)
	}
}

func TestParseIgnoresGoRunSeparator(t *testing.T) {
	opt, err := Parse([]string{"--", "-Command", "doctor", "-Pack", "_template"})
	if err != nil {
		t.Fatal(err)
	}
	if opt.Command != "doctor" || opt.Pack != "_template" || !opt.PackProvided {
		t.Fatalf("unexpected options after -- separator: %+v", opt)
	}
}

func TestParseDefaults(t *testing.T) {
	opt, err := Parse(nil)
	if err != nil {
		t.Fatal(err)
	}
	if opt.Command != "status" {
		t.Fatalf("Command = %q, want status", opt.Command)
	}
	if opt.Pack != defaults.DefaultPack {
		t.Fatalf("Pack = %q, want %s", opt.Pack, defaults.DefaultPack)
	}
}

func TestParseNextBatchPlanningReceiptFlags(t *testing.T) {
	opt, err := Parse([]string{"next-batch", "-Domain", "mission-commander", "-Closure", "Mission Control next-batch acceptance", "-ExpectedNextBatchPlanSha256", "abc123", "-Apply", "-Format", "json"})
	if err != nil {
		t.Fatal(err)
	}
	if opt.Command != commands.NextBatch || opt.NextBatchDomain != "mission-commander" || opt.NextBatchClosure != "Mission Control next-batch acceptance" || opt.ExpectedNextBatchPlanSHA256 != "abc123" || !opt.Apply || opt.WhatIf || opt.Format != "json" {
		t.Fatalf("unexpected next-batch options: %+v", opt)
	}
}

func TestRunNextBatchWhatIfReturnsHashBoundDocsReceipt(t *testing.T) {
	fixture := newCLIFixture(t, cliFixtureOptions{})
	restore := withNextBatchReadyReleaseCheckFixture(t, "Batch 945")
	defer restore()
	beforePlan := readFixtureFile(t, fixture.repoRoot, "docs/batch-plan.md")
	beforeChangelog := readFixtureFile(t, fixture.repoRoot, "CHANGELOG.md")

	var out bytes.Buffer
	if err := Run([]string{"-Command", "next-batch", "-Domain", "mission-commander", "-Closure", "Mission Control next-batch acceptance product path", "-WhatIf", "-Format", "json"}, &out); err != nil {
		t.Fatalf("next-batch WhatIf failed: %v\n%s", err, out.String())
	}
	var result nextBatchResult
	if err := json.Unmarshal(out.Bytes(), &result); err != nil {
		t.Fatalf("next-batch WhatIf JSON did not decode: %v\n%s", err, out.String())
	}
	if result.Command != commands.NextBatch || result.RepoRoot != fixture.repoRoot || result.IsMutation || result.Applied || !result.ReviewRequired || !result.RequiresConfirmation || result.LatestCompletedBatch != "Batch 945" || result.NextBatch != "Batch 946" || result.Domain != "mission-commander" || result.DomainActionID != "next-batch-mission-commander-operational-closure" || result.Closure != "Mission Control next-batch acceptance product path" {
		t.Fatalf("unexpected next-batch WhatIf envelope: %+v", result)
	}
	if len(result.ExpectedNextBatchPlanSHA256) != 64 || len(result.Writes) != 2 || result.Writes[0].Path != "docs/batch-plan.md" || result.Writes[0].Action != "insert-current-batch-section" || !result.Writes[0].Changed || result.Writes[1].Path != "CHANGELOG.md" || result.Writes[1].Action != "insert-unreleased-changelog-entry" || !result.Writes[1].Changed {
		t.Fatalf("unexpected next-batch write plan: sha=%q writes=%+v", result.ExpectedNextBatchPlanSHA256, result.Writes)
	}
	if !strings.Contains(result.CurrentBatchSection, "### Batch 946：Mission Control next-batch acceptance product path") || !strings.Contains(result.CurrentBatchSection, "`/rekit next-batch`") || !strings.Contains(result.ChangelogEntry, "Batch 946") || !strings.Contains(result.ChangelogEntry, "expectedNextBatchPlanSha256") || !containsSubstring(result.Boundary, "writes only kit docs") {
		t.Fatalf("next-batch receipt omitted section/changelog/boundary: section=%s changelog=%s boundary=%+v", result.CurrentBatchSection, result.ChangelogEntry, result.Boundary)
	}
	request := result.MissionCommanderActionQueue.CurrentDriverRequest
	if request == nil || request.Kind != "preview-command" || request.RunLoopStepID != "preview-current" || !request.CommandExecutable || !request.RequiresReview || request.Command == "" || strings.Contains(request.Command, " -Target ") || !strings.Contains(request.Command, "-ExpectedNextBatchPlanSha256 "+result.ExpectedNextBatchPlanSHA256) || !strings.Contains(request.Command, "-Apply -Format json") {
		t.Fatalf("next-batch WhatIf should return hash-bound apply driver request: %+v", request)
	}
	if afterPlan := readFixtureFile(t, fixture.repoRoot, "docs/batch-plan.md"); afterPlan != beforePlan {
		t.Fatal("next-batch WhatIf mutated docs/batch-plan.md")
	}
	if afterChangelog := readFixtureFile(t, fixture.repoRoot, "CHANGELOG.md"); afterChangelog != beforeChangelog {
		t.Fatal("next-batch WhatIf mutated CHANGELOG.md")
	}
}

func TestRunNextBatchWhatIfUsesSelectedDomainCandidateGuidance(t *testing.T) {
	fixture := newCLIFixture(t, cliFixtureOptions{})
	restore := withNextBatchReadyReleaseCheckFixture(t, "Batch 945")
	defer restore()

	var out bytes.Buffer
	if err := Run([]string{"-Command", "next-batch", "-Domain", "replacement-executor", "-Closure", "Replacement executor status driver consumption path", "-WhatIf", "-Format", "json"}, &out); err != nil {
		t.Fatalf("next-batch replacement-executor WhatIf failed: %v\n%s", err, out.String())
	}
	var result nextBatchResult
	if err := json.Unmarshal(out.Bytes(), &result); err != nil {
		t.Fatalf("next-batch replacement-executor WhatIf JSON did not decode: %v\n%s", err, out.String())
	}
	if result.RepoRoot != fixture.repoRoot || result.Domain != "replacement-executor" || result.DomainActionID != "next-batch-replacement-executor-takeover" {
		t.Fatalf("unexpected replacement-executor WhatIf envelope: %+v", result)
	}
	for _, text := range []string{result.CurrentBatchSection, result.ChangelogEntry} {
		if !strings.Contains(text, "replacement executor takeover slice") || !strings.Contains(text, "status or durable handoff without prior chat context") {
			t.Fatalf("replacement-executor receipt omitted selected candidate guidance:\n%s", text)
		}
		if strings.Contains(text, "next-batch selection guidance acceptance") || strings.Contains(text, "新增 `/rekit next-batch` kit review-first command") || strings.Contains(text, "PowerShell façade no-fallback delegation") {
			t.Fatalf("replacement-executor receipt leaked previous next-batch acceptance template:\n%s", text)
		}
	}
}

func TestRunNextBatchGuidancePlanningRouteConsumerLoopProductPath(t *testing.T) {
	fixture := newCLIFixture(t, cliFixtureOptions{})
	restore := withNextBatchReadyReleaseCheckFixture(t, "Batch 945")
	restored := false
	defer func() {
		if !restored {
			restore()
		}
	}()
	beforePlan := readFixtureFile(t, fixture.repoRoot, "docs/batch-plan.md")
	beforeChangelog := readFixtureFile(t, fixture.repoRoot, "CHANGELOG.md")

	var out bytes.Buffer
	if err := Run([]string{"-Command", "status", "-Format", "json"}, &out); err != nil {
		t.Fatalf("status before next-batch planning route failed: %v\n%s", err, out.String())
	}
	var status struct {
		MissionControlRunbook *statusMissionControlRunbookSnapshot `json:"missionControlRunbook"`
	}
	if err := json.Unmarshal(out.Bytes(), &status); err != nil {
		t.Fatalf("status JSON before next-batch planning route did not decode: %v\n%s", err, out.String())
	}
	guidance := status.MissionControlRunbook.GuidanceHandoff
	if guidance == nil || !guidance.Ready || guidance.Source != "releaseHandoffNextBatch" || len(guidance.NextBatchPlanningRoutes) == 0 {
		t.Fatalf("status guidance handoff omitted next-batch planning routes: runbook=%+v", status.MissionControlRunbook)
	}
	var route struct {
		Ready                   bool     `json:"ready"`
		Domain                  string   `json:"domain"`
		DomainActionID          string   `json:"domainActionId"`
		ClosurePlaceholder      string   `json:"closurePlaceholder"`
		WhatIfCommandTemplate   string   `json:"whatIfCommandTemplate"`
		CommandExecutable       bool     `json:"commandExecutable"`
		RequiresReview          bool     `json:"requiresReview"`
		RefreshStatusCommand    string   `json:"refreshStatusCommand"`
		ExpectedApplySource     string   `json:"expectedApplySource"`
		ExpectedApplyDriverKind string   `json:"expectedApplyDriverKind"`
		RunbookSteps            []string `json:"runbookSteps"`
		Boundary                []string `json:"boundary"`
	}
	for _, item := range guidance.NextBatchPlanningRoutes {
		if item.Domain == "mission-commander" {
			route = item
			break
		}
	}
	if !route.Ready || route.DomainActionID != "next-batch-mission-commander-operational-closure" || route.CommandExecutable || !route.RequiresReview || route.ExpectedApplySource != "nextBatchCommand" || route.ExpectedApplyDriverKind != "preview-command" || route.RefreshStatusCommand != status.MissionControlRunbook.RefreshStatusCommand || !strings.Contains(route.WhatIfCommandTemplate, route.ClosurePlaceholder) || !containsSubstring(route.RunbookSteps, "replace closurePlaceholder") || !containsSubstring(route.Boundary, "status does not choose a batch") {
		t.Fatalf("mission-commander planning route drifted: %+v", route)
	}
	concreteClosure := "next-batch guidance driver request planning loop"
	whatIfCommand := strings.Replace(route.WhatIfCommandTemplate, route.ClosurePlaceholder, concreteClosure, 1)
	out.Reset()
	if err := Run(rekitCommandCLIArgs(t, whatIfCommand), &out); err != nil {
		t.Fatalf("next-batch WhatIf from status planning route failed: command=%s err=%v\n%s", whatIfCommand, err, out.String())
	}
	var preview nextBatchResult
	if err := json.Unmarshal(out.Bytes(), &preview); err != nil {
		t.Fatalf("next-batch route WhatIf JSON did not decode: %v\n%s", err, out.String())
	}
	if preview.IsMutation || preview.Applied || preview.Domain != route.Domain || preview.DomainActionID != route.DomainActionID || preview.Closure != concreteClosure || len(preview.ExpectedNextBatchPlanSHA256) != 64 {
		t.Fatalf("next-batch route WhatIf result drifted: %+v", preview)
	}
	if readFixtureFile(t, fixture.repoRoot, "docs/batch-plan.md") != beforePlan || readFixtureFile(t, fixture.repoRoot, "CHANGELOG.md") != beforeChangelog {
		t.Fatal("next-batch route WhatIf mutated kit docs")
	}
	applyRequest := requireTypedMissionCommanderDriverRequest(t, preview.MissionCommanderActionQueue, "preview-command", "preview-current", preview.MissionCommanderAction.Command, true, false, true)
	if !strings.Contains(applyRequest.Command, "-ExpectedNextBatchPlanSha256 "+preview.ExpectedNextBatchPlanSHA256) || !strings.Contains(applyRequest.Command, "-Apply -Format json") {
		t.Fatalf("route WhatIf omitted hash-bound Apply driver request: request=%+v preview=%+v", applyRequest, preview)
	}
	applyArgs, ok := typedMissionCommanderDriverRequestCommandCLIArgs(t, applyRequest)
	if !ok {
		t.Fatalf("hash-bound next-batch Apply request should be executable: %+v", applyRequest)
	}
	out.Reset()
	if err := Run(applyArgs, &out); err != nil {
		t.Fatalf("next-batch Apply from returned driver request failed: command=%s err=%v\n%s", applyRequest.Command, err, out.String())
	}
	var applied nextBatchResult
	if err := json.Unmarshal(out.Bytes(), &applied); err != nil {
		t.Fatalf("next-batch route Apply JSON did not decode: %v\n%s", err, out.String())
	}
	if !applied.IsMutation || !applied.Applied || applied.ExpectedNextBatchPlanSHA256 != preview.ExpectedNextBatchPlanSHA256 {
		t.Fatalf("next-batch route Apply result drifted: %+v", applied)
	}
	statusRequest := requireTypedMissionCommanderDriverRequest(t, applied.MissionCommanderActionQueue, "execute-command", "apply-or-run-current", "/rekit status -Format json", true, false, false)
	statusArgs, ok := typedMissionCommanderDriverRequestCommandCLIArgs(t, statusRequest)
	if !ok {
		t.Fatalf("next-batch Apply returned status refresh request should be executable: %+v", statusRequest)
	}

	restore()
	restored = true
	out.Reset()
	if err := Run(statusArgs, &out); err != nil {
		t.Fatalf("status refresh from next-batch Apply driver request failed: %v\n%s", err, out.String())
	}
	var refreshed struct {
		ProjectHandoff struct {
			LatestBatch                 string                              `json:"latestBatch"`
			LatestBatchStatus           string                              `json:"latestBatchStatus"`
			MissionCommanderActionQueue missionCommanderActionQueueSnapshot `json:"missionCommanderActionQueue"`
		} `json:"projectHandoff"`
		MissionControlRunbook *statusMissionControlRunbookSnapshot `json:"missionControlRunbook"`
	}
	if err := json.Unmarshal(out.Bytes(), &refreshed); err != nil {
		t.Fatalf("status refresh after route Apply did not decode: %v\n%s", err, out.String())
	}
	current := refreshed.ProjectHandoff.MissionCommanderActionQueue.CurrentAction
	if refreshed.ProjectHandoff.LatestBatch != "Batch 946" || !strings.Contains(refreshed.ProjectHandoff.LatestBatchStatus, "进行中") || current == nil || current.ActionID != "latest-batch-next-action" || refreshed.MissionControlRunbook == nil || refreshed.MissionControlRunbook.GuidanceHandoff == nil || refreshed.MissionControlRunbook.GuidanceHandoff.Source == "releaseHandoffNextBatch" {
		t.Fatalf("status refresh should consume durable route Apply docs as current in-progress batch: project=%+v runbook=%+v", refreshed.ProjectHandoff, refreshed.MissionControlRunbook)
	}
}

func TestRunNextBatchApplyRequiresWhatIfHashAndRefreshesStatus(t *testing.T) {
	fixture := newCLIFixture(t, cliFixtureOptions{})
	restore := withNextBatchReadyReleaseCheckFixture(t, "Batch 945")
	restored := false
	defer func() {
		if !restored {
			restore()
		}
	}()

	var out bytes.Buffer
	if err := Run([]string{"-Command", "next-batch", "-Domain", "replacement-executor", "-Closure", "replacement executor durable next-batch receipt", "-Apply", "-Format", "json"}, &out); err == nil || !strings.Contains(err.Error(), "requires -ExpectedNextBatchPlanSha256") {
		t.Fatalf("next-batch Apply without expected hash should fail, err=%v stdout=%s", err, out.String())
	}
	out.Reset()
	if err := Run([]string{"-Command", "next-batch", "-Domain", "replacement-executor", "-Closure", "replacement executor durable next-batch receipt", "-ExpectedNextBatchPlanSha256", strings.Repeat("0", 64), "-WhatIf", "-Format", "json"}, &out); err == nil || !strings.Contains(err.Error(), "WhatIf does not accept") {
		t.Fatalf("next-batch WhatIf with expected hash should fail, err=%v stdout=%s", err, out.String())
	}
	out.Reset()
	if err := Run([]string{"-Command", "next-batch", "-Target", fixture.repoRoot, "-Domain", "replacement-executor", "-Closure", "replacement executor durable next-batch receipt", "-WhatIf", "-Format", "json"}, &out); err == nil || !strings.Contains(err.Error(), "omit -Target") {
		t.Fatalf("next-batch with target should fail, err=%v stdout=%s", err, out.String())
	}

	out.Reset()
	if err := Run([]string{"-Command", "next-batch", "-Domain", "replacement-executor", "-Closure", "replacement executor durable next-batch receipt", "-WhatIf", "-Format", "json"}, &out); err != nil {
		t.Fatalf("next-batch WhatIf failed: %v\n%s", err, out.String())
	}
	var preview nextBatchResult
	if err := json.Unmarshal(out.Bytes(), &preview); err != nil {
		t.Fatalf("next-batch WhatIf JSON did not decode: %v\n%s", err, out.String())
	}
	out.Reset()
	if err := Run([]string{"-Command", "next-batch", "-Domain", "replacement-executor", "-Closure", "replacement executor durable next-batch receipt", "-ExpectedNextBatchPlanSha256", strings.Repeat("f", 64), "-Apply", "-Format", "json"}, &out); err == nil || !strings.Contains(err.Error(), "expected plan sha256 mismatch") {
		t.Fatalf("next-batch Apply with wrong hash should fail, err=%v stdout=%s", err, out.String())
	}

	out.Reset()
	if err := Run([]string{"-Command", "next-batch", "-Domain", "replacement-executor", "-Closure", "replacement executor durable next-batch receipt", "-ExpectedNextBatchPlanSha256", preview.ExpectedNextBatchPlanSHA256, "-Apply", "-Format", "json"}, &out); err != nil {
		t.Fatalf("next-batch Apply failed: %v\n%s", err, out.String())
	}
	var applied nextBatchResult
	if err := json.Unmarshal(out.Bytes(), &applied); err != nil {
		t.Fatalf("next-batch Apply JSON did not decode: %v\n%s", err, out.String())
	}
	if !applied.IsMutation || !applied.Applied || applied.ReviewRequired || applied.RequiresConfirmation || applied.ExpectedNextBatchPlanSHA256 != preview.ExpectedNextBatchPlanSHA256 {
		t.Fatalf("unexpected next-batch Apply envelope: %+v", applied)
	}
	request := applied.MissionCommanderActionQueue.CurrentDriverRequest
	if request == nil || request.Kind != "execute-command" || request.Command != "/rekit status -Format json" || request.RequiresReview || !request.CommandExecutable || !containsSubstring(applied.NextSteps, "status -Format json") {
		t.Fatalf("next-batch Apply should return status refresh driver request: request=%+v next=%+v", request, applied.NextSteps)
	}
	if plan := readFixtureFile(t, fixture.repoRoot, "docs/batch-plan.md"); !strings.Contains(plan, "### Batch 946：replacement executor durable next-batch receipt") || !strings.Contains(plan, "`/rekit next-batch`") {
		t.Fatalf("next-batch Apply did not write docs/batch-plan.md receipt:\n%s", plan)
	}
	if changelog := readFixtureFile(t, fixture.repoRoot, "CHANGELOG.md"); !strings.Contains(changelog, "Batch 946 新增 replacement executor durable next-batch receipt") || !strings.Contains(changelog, "expectedNextBatchPlanSha256") {
		t.Fatalf("next-batch Apply did not write CHANGELOG.md receipt:\n%s", changelog)
	}

	restore()
	restored = true
	out.Reset()
	if err := Run([]string{"-Command", "status", "-Format", "json"}, &out); err != nil {
		t.Fatalf("status refresh after next-batch Apply failed: %v\n%s", err, out.String())
	}
	var status struct {
		ProjectHandoff struct {
			LatestBatch                 string                              `json:"latestBatch"`
			LatestBatchStatus           string                              `json:"latestBatchStatus"`
			LatestNextAction            string                              `json:"latestNextAction"`
			MissionCommanderActionQueue missionCommanderActionQueueSnapshot `json:"missionCommanderActionQueue"`
		} `json:"projectHandoff"`
		MissionControlRunbook *statusMissionControlRunbookSnapshot `json:"missionControlRunbook"`
	}
	if err := json.Unmarshal(out.Bytes(), &status); err != nil {
		t.Fatalf("status JSON after next-batch Apply did not decode: %v\n%s", err, out.String())
	}
	current := status.ProjectHandoff.MissionCommanderActionQueue.CurrentAction
	if status.ProjectHandoff.LatestBatch != "Batch 946" || !strings.Contains(status.ProjectHandoff.LatestBatchStatus, "进行中") || !strings.Contains(status.ProjectHandoff.LatestNextAction, "finish the current batch") || current == nil || current.Command == "" || current.ActionID != "latest-batch-next-action" || current.Source != "releaseHandoffLatestBatch" || status.MissionControlRunbook == nil || status.MissionControlRunbook.GuidanceHandoff == nil || status.MissionControlRunbook.GuidanceHandoff.Source == "releaseHandoffNextBatch" {
		t.Fatalf("status refresh should consume durable next-batch docs as current in-progress batch: project=%+v runbook=%+v", status.ProjectHandoff, status.MissionControlRunbook)
	}
}

func readFixtureFile(t *testing.T, root, rel string) string {
	t.Helper()
	data, err := os.ReadFile(filepath.Join(root, filepath.FromSlash(rel)))
	if err != nil {
		t.Fatal(err)
	}
	return string(data)
}

func TestStatusProjectHandoffCurrentActionPromotesCompletedCadenceToNextBatchSelection(t *testing.T) {
	remoteDetail := &releasecheck.ReleaseHandoffRemoteReleaseGateDetail{
		State:            "blocked: completed failure with jobs steps=[]",
		EmptySteps:       true,
		CompletedFailure: true,
		CanClaimGreen:    false,
		Boundary:         []string{"treat remote release-gate steps=[] as a known runner/billing blocker"},
	}
	cadence := releasecheck.ReleaseHandoffReleaseInspectionCadence{
		State:                     "complete",
		ImplementationCommitReady: true,
		InspectionCommitReady:     true,
		Boundary:                  []string{"do not add a third record commit for the release inspection commit's own CI run"},
	}
	pkg := releasecheck.BuildNextBatchSelectionPackage(releasecheck.ReleaseHandoff{
		Ready: true,
		LatestBatch: releasecheck.ReleaseHandoffLatestBatch{
			BatchID: "Batch 651",
			Handoff: releasecheck.ReleaseHandoffLatestBatchHandoff{
				LocalValidationReady:     true,
				ReleaseCheckReady:        true,
				RemoteReleaseGate:        "blocked: completed failure with jobs steps=[]",
				RemoteReleaseGateDetail:  remoteDetail,
				ReleaseInspectionCadence: cadence,
				CommitRefs:               []string{"def651a"},
			},
		},
		PackMemoryCandidates: releasecheck.ReleaseHandoffPackMemoryCandidateList{
			Ready:      true,
			NextAction: "no pack-memory candidate cleanup is pending",
		},
	})
	if pkg == nil {
		t.Fatal("expected next-batch selection package fixture")
	}
	project := &statusProjectHandoff{
		Ready:                         true,
		LatestBatch:                   "Batch 651",
		LatestLocalValidationReady:    true,
		LatestReleaseCheckReady:       true,
		LatestRemoteReleaseGate:       "blocked: completed failure with jobs steps=[]",
		LatestRemoteReleaseGateDetail: remoteDetail,
		ReleaseInspectionCadence:      cadence,
		ReadFirst:                     []string{"docs/context-routing.md", "docs/batch-plan.md"},
		ValidationCommands:            []string{"go test ./..."},
		NextBatchSelectionPackage:     pkg,
	}
	action := statusProjectHandoffCurrentAction(project)
	if action == nil || action.Label != "next-batch" || action.ActionID != "next-batch-selection" || action.State != "ready-for-next-batch-selection" || action.Source != "releaseHandoffNextBatch" || action.RequiresReview || !strings.Contains(action.Command, "select the next Windows-verifiable product-path closure") {
		t.Fatalf("completed cadence should promote to next-batch selection: %+v", action)
	}
	if !containsSubstring(action.Reasons, "ready for the next Windows-verifiable product-path batch") || !containsSubstring(action.Boundary, "avoid single-field") || !containsSubstring(action.Boundary, "steps=[]") {
		t.Fatalf("next-batch action omitted reasons/boundary: %+v", action)
	}
	steps := statusProjectHandoffRunbookSteps(project, action)
	for _, want := range []string{"confirm git status is clean", "choose a Windows-verifiable product-path closure", "write the selected Batch state", "full local release minimum", "steps=[] blocker"} {
		if !containsSubstring(steps, want) {
			t.Fatalf("next-batch runbook missing %q: %+v", want, steps)
		}
	}
}

func TestStatusProjectHandoffLocalValidationActionUsesReleaseRunDriverRequest(t *testing.T) {
	project := &statusProjectHandoff{
		Ready:                       true,
		LatestBatch:                 "Batch 744",
		LatestNextAction:            "run the full local release minimum and update docs/batch-plan.md",
		LatestRemoteReleaseGate:     "not-recorded",
		ReleaseInspectionCadence:    releasecheck.ReleaseHandoffReleaseInspectionCadence{State: "implementation-pending", NextAction: "create/push the implementation commit after local validation", Boundary: []string{"normal batches stop after implementation commit/push plus one release inspection commit/push"}},
		ValidationCommands:          []string{"go run ./cmd/rekit -- -Command release-check -Format json", "go test ./..."},
		PackMemoryCandidates:        releasecheck.ReleaseHandoffPackMemoryCandidateList{Ready: true, NextAction: "no pack-memory candidate cleanup is pending"},
		MissionCommanderNextActions: nil,
	}
	project.MissionCommanderNextActions = statusProjectHandoffMissionCommanderNextActions(project)
	project.MissionCommanderActionQueue = mission.MissionCommanderActionQueueFor(project.MissionCommanderNextActions)
	current := project.MissionCommanderActionQueue.CurrentAction
	if current == nil || current.Command != "/rekit release-run -Format json" || current.Source != "releaseHandoffLatestBatch" || current.State != "implementation-pending" || !current.RequiresReview || !containsSubstring(current.Reasons, "local release minimum can be executed through release-run") || !containsSubstring(current.Boundary, "release-run executes the local release minimum") {
		t.Fatalf("implementation-pending project action should expose release-run driver command: current=%+v queue=%+v", current, project.MissionCommanderActionQueue)
	}
	request := requireTypedMissionCommanderDriverRequest(t, project.MissionCommanderActionQueue, "preview-command", "preview-current", "/rekit release-run -Format json", true, false, true)
	if request.ExpectedReceipt.Command != "/rekit release-run -Format json" || !containsSubstring(request.Boundary, "review-required current actions") {
		t.Fatalf("release-run driver request should be preview/review-required with same-command receipt: %+v", request)
	}
	runbook := buildStatusMissionControlRunbook("C:/case-root", nil, project)
	if runbook == nil || runbook.CurrentDriverRequest == nil || runbook.CurrentDriverRequest.Command != "/rekit release-run -Format json" || runbook.CurrentDriverRequest.Kind != "preview-command" || strings.Contains(runbook.CurrentDriverRequest.Command, " -Target ") || runbook.CurrentDriverRequest.ExpectedReceipt.Command != "/rekit release-run -Format json" || runbook.CurrentDriverRequest.ExpectedReceipt.RefreshStatusCommand != runbook.RefreshStatusCommand || runbook.GuidanceHandoff != nil {
		t.Fatalf("status runbook should preserve kit-scoped release-run command with refresh receipt: %+v", runbook)
	}
	args, ok := typedMissionCommanderDriverRequestCommandCLIArgs(t, runbook.CurrentDriverRequest)
	if !ok || !slices.Equal(args, []string{"-Command", "release-run", "-Format", "json"}) {
		t.Fatalf("release-run driver request should produce CLI args: args=%+v ok=%t request=%+v", args, ok, runbook.CurrentDriverRequest)
	}
	var out bytes.Buffer
	if err := writeStatusMissionControlRunbookText(&out, runbook); err != nil {
		t.Fatal(err)
	}
	for _, want := range []string{
		"status Mission Control runbook driver：kind=preview-command",
		"command=/rekit release-run -Format json",
		"status Mission Control runbook step：order=2 step=consume-focused-driver-request",
		"status Mission Control runbook driver request expected receipt：state=refresh-required command=`/rekit release-run -Format json` refreshStatusCommand=`" + runbook.RefreshStatusCommand + "`",
		"status Mission Control runbook step boundary：step=consume-focused-driver-request boundary=review-required current actions must be previewed or reviewed before any apply/follow-up",
	} {
		if !strings.Contains(out.String(), want) {
			t.Fatalf("release-run status runbook text missing %q:\n%s", want, out.String())
		}
	}
}

