func TestStatusMissionCommanderFirstScreenFocusUsesCrossSubsystemPriority(t *testing.T) {
	project := &mission.MissionCommanderNextActionItem{Command: "/rekit status", Source: "releaseHandoffLatestBatch", State: "complete"}
	passiveReviewer := &mission.MissionCommanderNextActionItem{Command: "dispatch read-only reviewer", Source: "reviewerDispatchIntakeHandoffs", State: "ready-for-reviewer-dispatch", RequiresReview: true}
	packInProgress := &mission.MissionCommanderNextActionItem{Command: "/rekit promote -ExpectedProvisionSha256 provision-sha -Apply -Format json", Source: "packMemoryCandidates._template", State: "pack-memory-verification-required", ActionID: "pack-memory-verification-provision-in-progress", RequiresReview: true}
	packProject := &statusProjectHandoff{PackMemoryCandidates: releasecheck.ReleaseHandoffPackMemoryCandidateList{Ready: false, Total: 1}}
	focus := statusMissionCommanderFirstScreenFocus(nil, passiveReviewer, project, packProject, packInProgress)
	if focus != "pack-memory-current-action" {
		t.Fatalf("pack-memory in-progress closure should outrank passive reviewer wait: focus=%s reviewer=%+v pack=%+v", focus, passiveReviewer, packInProgress)
	}
	reasons := statusMissionCommanderFirstScreenFocusRoutingReasons(focus, nil, passiveReviewer, project, packProject, packInProgress)
	if !containsSubstring(reasons, "pack-memory candidate queue still needs review or closure") || !containsSubstring(reasons, "deferred focus queues: reviewer,project") {
		t.Fatalf("pack-memory cross-subsystem routing reasons drifted: %+v", reasons)
	}

	reviewerReady := &mission.MissionCommanderNextActionItem{Command: "/rekit plan-subagents -ReadyReviewerResults -WhatIf -Format json", Source: "reviewerDispatchIntakeHandoffs", State: "ready-for-reviewer-intake-preview", RequiresReview: true}
	packProof := &mission.MissionCommanderNextActionItem{Command: "/rekit promote -DraftReviewProof -WhatIf -Format json", Source: "packMemoryCandidates._template", State: "pack-memory-proof-required", ActionID: "pack-memory-decision-proof-required", RequiresReview: true}
	focus = statusMissionCommanderFirstScreenFocus(nil, reviewerReady, project, packProject, packProof)
	if focus != "reviewer-current-action" {
		t.Fatalf("reviewer ready intake should outrank ordinary pack-memory proof follow-up: focus=%s reviewer=%+v pack=%+v", focus, reviewerReady, packProof)
	}
}

func TestStatusProjectHandoffNextBatchCandidateDomainsOnlyAfterCompleteCadence(t *testing.T) {
	complete := buildStatusProjectHandoff(releasecheck.ReleaseHandoff{
		Ready:   true,
		Summary: "release handoff summary ok",
		LatestBatch: releasecheck.ReleaseHandoffLatestBatch{
			BatchID: "Batch 681",
			Handoff: releasecheck.ReleaseHandoffLatestBatchHandoff{
				LocalValidationReady: true,
				ReleaseCheckReady:    true,
				RemoteReleaseGate:    "blocked: completed failure with jobs steps=[]",
				ReleaseInspectionCadence: releasecheck.ReleaseHandoffReleaseInspectionCadence{
					State:                     "complete",
					ImplementationCommitReady: true,
					InspectionCommitReady:     true,
					Boundary:                  []string{"do not add a third record commit"},
				},
			},
		},
		PackMemoryCandidates: releasecheck.ReleaseHandoffPackMemoryCandidateList{Ready: true, Summary: "pack-memory candidate inventory ok", NextAction: "no pack-memory candidate cleanup is pending"},
	})
	if complete.NextBatchSelectionPackage == nil || !complete.NextBatchSelectionPackage.Ready || complete.NextBatchSelectionPackage.MissionCommanderActionQueue.Counts.Total != 8 || complete.NextBatchSelectionPackage.StarterPackage == nil || complete.NextBatchSelectionPackage.StarterPackage.SuggestedNextBatch != "Batch 682" || !strings.Contains(complete.NextBatchSelectionPackage.StarterPackage.CurrentBatchSection, "### Batch 682") {
		t.Fatalf("complete cadence should bind release-check next-batch selection package with starter: %+v", complete.NextBatchSelectionPackage)
	}
	starter := complete.NextBatchSelectionPackage.StarterPackage
	if starter.CurrentRunLoopStepID != "select-candidate-domain" || len(starter.RunLoop) < 6 || starter.RunLoop[0].StepID != "select-candidate-domain" || starter.RunLoop[len(starter.RunLoop)-1].StepID != "commit-and-inspect" {
		t.Fatalf("complete cadence should expose ordered starter run loop: %+v", starter)
	}
	if complete.MissionCommanderActionQueue.CurrentAction == nil || complete.MissionCommanderActionQueue.CurrentAction.ActionID != "next-batch-selection" || complete.MissionCommanderActionQueue.Counts.Total != 8 || complete.MissionCommanderActionQueue.Counts.FollowUp != 7 {
		t.Fatalf("complete cadence should expose current next-batch selection plus candidate-domain follow-ups: %+v", complete.MissionCommanderActionQueue)
	}
	if !slices.ContainsFunc(complete.MissionCommanderNextActions, func(item mission.MissionCommanderNextActionItem) bool {
		return item.ActionID == "next-batch-pack-memory-ux" && containsSubstring(item.Reasons, "pack-memory candidate queue is closed: no pack-memory candidate cleanup is pending") && containsSubstring(item.Boundary, "candidate-domain follow-ups are selection guidance only")
	}) {
		t.Fatalf("complete cadence next-batch candidate domains omitted product-path guidance: %+v", complete.MissionCommanderNextActions)
	}

	incomplete := buildStatusProjectHandoff(releasecheck.ReleaseHandoff{
		Ready:   true,
		Summary: "release handoff summary ok",
		LatestBatch: releasecheck.ReleaseHandoffLatestBatch{
			BatchID: "Batch 682",
			Handoff: releasecheck.ReleaseHandoffLatestBatchHandoff{
				LocalValidationReady: false,
				ReleaseCheckReady:    false,
				NextAction:           "run the full local release minimum before handoff",
				ReleaseInspectionCadence: releasecheck.ReleaseHandoffReleaseInspectionCadence{
					State:      "implementation-pending",
					NextAction: "run the full local release minimum before handoff",
				},
			},
		},
		PackMemoryCandidates: releasecheck.ReleaseHandoffPackMemoryCandidateList{Ready: true, Summary: "pack-memory candidate inventory ok", NextAction: "no pack-memory candidate cleanup is pending"},
	})
	if incomplete.MissionCommanderActionQueue.CurrentAction == nil || incomplete.MissionCommanderActionQueue.CurrentAction.Source != "releaseHandoffLatestBatch" || incomplete.MissionCommanderActionQueue.Counts.Total != 1 || incomplete.MissionCommanderActionQueue.Counts.FollowUp != 0 || slices.ContainsFunc(incomplete.MissionCommanderNextActions, func(item mission.MissionCommanderNextActionItem) bool {
		return item.ActionID == "next-batch-pack-memory-ux"
	}) {
		t.Fatalf("incomplete cadence should keep latest-batch action without candidate-domain follow-ups: %+v actions=%+v", incomplete.MissionCommanderActionQueue, incomplete.MissionCommanderNextActions)
	}
}

