type releaseCheckPowerShellDeprecation = releasecheck.PowerShellDeprecation

type releaseCheckResult = releasecheck.Result

func TestRunReleaseRunUsesResolvedGateProfileSteps(t *testing.T) {
	previous := releaseRunExecuteCommand
	defer func() { releaseRunExecuteCommand = previous }()

	calls := []string{}
	releaseRunExecuteCommand = func(ctx context.Context, repoRoot, command string) (int, string, error) {
		calls = append(calls, command)
		return 0, "ok: " + command, nil
	}

	var out bytes.Buffer
	if err := Run([]string{"-Command", "release-run", "-Format", "json"}, &out); err != nil {
		t.Fatal(err)
	}
	var result releaseRunResult
	if err := json.Unmarshal(out.Bytes(), &result); err != nil {
		t.Fatalf("release-run JSON did not decode: %v\n%s", err, out.String())
	}
	if result.Command != "release-run" || result.SchemaVersion != 1 || result.IsMutation || !result.Ready || result.Summary != "release run ok" || result.StepCount != 7 || result.Passed != 7 || result.Failed != 0 || result.Skipped != 0 || len(result.Steps) != 7 || len(calls) != 7 {
		t.Fatalf("unexpected release-run result: result=%+v calls=%+v", result, calls)
	}
	if calls[0] != "go run ./cmd/rekit -- -Command release-check -Format json" || calls[len(calls)-1] != "git diff --check" {
		t.Fatalf("release-run did not preserve gate profile command order: %v", calls)
	}
	for _, step := range result.Steps {
		if step.Status != "passed" || step.ExitCode != 0 || strings.TrimSpace(step.OutputTail) == "" {
			t.Fatalf("release-run step missing success summary: %+v", step)
		}
	}

	out.Reset()
	if err := Run([]string{"-Command", "release-run", "-Format", "text"}, &out); err != nil {
		t.Fatal(err)
	}
	for _, expected := range []string{
		"release-run：mutation=false ready=true summary=release run ok",
		"release-run step：index=1 status=passed exitCode=0",
		"command=go run ./cmd/rekit -- -Command release-check -Format json",
		"release-run boundary：does not write repo or case state",
	} {
		if !strings.Contains(out.String(), expected) {
			t.Fatalf("release-run text missing %q:\n%s", expected, out.String())
		}
	}
}

func TestRunReleaseRunIncludesReleaseInspectionHandoff(t *testing.T) {
	previousCommand := releaseRunExecuteCommand
	previousGit := releaseRunExecuteGitCommand
	restoreReleaseCheck := withReadyReleaseCheckFixture(t)
	defer restoreReleaseCheck()
	defer func() {
		releaseRunExecuteCommand = previousCommand
		releaseRunExecuteGitCommand = previousGit
	}()
	releaseRunExecuteCommand = func(ctx context.Context, repoRoot, command string) (int, string, error) {
		return 0, "ok: " + command, nil
	}
	releaseRunExecuteGitCommand = fakeReleaseRunGit(map[string]fakeReleaseRunGitResult{
		"rev-parse --abbrev-ref HEAD":               {output: "main\n"},
		"rev-parse HEAD":                            {output: "abc123\n"},
		"rev-parse origin/main":                     {output: "abc123\n"},
		"status --short":                            {output: ""},
		"merge-base --is-ancestor HEAD origin/main": {output: ""},
		"merge-base --is-ancestor origin/main HEAD": {output: ""},
	})

	var out bytes.Buffer
	if err := Run([]string{"-Command", "release-run", "-Format", "json"}, &out); err != nil {
		t.Fatal(err)
	}
	var result releaseRunResult
	if err := json.Unmarshal(out.Bytes(), &result); err != nil {
		t.Fatalf("release-run JSON did not decode: %v\n%s", err, out.String())
	}
	inspection := result.ReleaseInspection
	if !inspection.Ready || inspection.Summary != "release inspection handoff ok; remote gate not green" || !inspection.LocalReleaseRunReady || inspection.Git.Branch != "main" || !inspection.Git.WorkingTreeClean || !inspection.Git.Synchronized || inspection.Git.Head != "abc123" || inspection.LatestBatch.BatchID == "" {
		t.Fatalf("unexpected release inspection handoff: %+v", inspection)
	}
	assertStringContains(t, inspection.Boundary, "ciReleaseGate.ready remains workflow inventory readiness, not remote green")
	assertStringContains(t, inspection.NextActions, "keep remote CI status truthful: inventory ready is not remote green")

	out.Reset()
	if err := Run([]string{"-Command", "release-run", "-Format", "text"}, &out); err != nil {
		t.Fatal(err)
	}
	for _, expected := range []string{
		"release-run release inspection：ready=true summary=release inspection handoff ok; remote gate not green",
		"release-run release inspection git：branch=main clean=true synchronized=true head=abc123 originMain=abc123",
		"release-run release inspection next action：keep remote CI status truthful: inventory ready is not remote green",
		"release-run release inspection boundary：does not fetch GitHub or inspect remote Actions live state",
	} {
		if !strings.Contains(out.String(), expected) {
			t.Fatalf("release-run release inspection text missing %q:\n%s", expected, out.String())
		}
	}
}

func TestRunReleaseRunReleaseInspectionBlocksDirtyUnsyncedHandoff(t *testing.T) {
	previousCommand := releaseRunExecuteCommand
	previousGit := releaseRunExecuteGitCommand
	defer func() {
		releaseRunExecuteCommand = previousCommand
		releaseRunExecuteGitCommand = previousGit
	}()
	releaseRunExecuteCommand = func(ctx context.Context, repoRoot, command string) (int, string, error) {
		return 0, "ok", nil
	}
	releaseRunExecuteGitCommand = fakeReleaseRunGit(map[string]fakeReleaseRunGitResult{
		"rev-parse --abbrev-ref HEAD":               {output: "feature\n"},
		"rev-parse HEAD":                            {output: "abc123\n"},
		"rev-parse origin/main":                     {output: "def456\n"},
		"status --short":                            {output: " M docs/batch-plan.md\n"},
		"merge-base --is-ancestor HEAD origin/main": {exitCode: 1, err: errors.New("exit status 1")},
		"merge-base --is-ancestor origin/main HEAD": {exitCode: 1, err: errors.New("exit status 1")},
	})

	var out bytes.Buffer
	if err := Run([]string{"-Command", "release-run", "-Format", "json"}, &out); err != nil {
		t.Fatal(err)
	}
	var result releaseRunResult
	if err := json.Unmarshal(out.Bytes(), &result); err != nil {
		t.Fatalf("release-run JSON did not decode: %v\n%s", err, out.String())
	}
	inspection := result.ReleaseInspection
	if inspection.Ready || inspection.Summary != "release inspection handoff blocked" || inspection.Git.Branch != "feature" || inspection.Git.WorkingTreeClean || inspection.Git.Synchronized || len(inspection.Warnings) < 3 {
		t.Fatalf("dirty/unsynced release inspection should be blocked: %+v", inspection)
	}
	assertStringContains(t, inspection.NextActions, "switch to main before release inspection handoff")
	assertStringContains(t, inspection.NextActions, "commit or revert working tree changes before declaring release inspection complete")
	assertStringContains(t, inspection.NextActions, "fetch/pull/push until local main and origin/main point at the same commit")
}

type fakeReleaseRunGitResult struct {
	exitCode int
	output   string
	err      error
}

func fakeReleaseRunGit(results map[string]fakeReleaseRunGitResult) releaseRunGitCommandExecutor {
	return func(ctx context.Context, repoRoot string, args ...string) (int, string, error) {
		key := strings.Join(args, " ")
		result, ok := results[key]
		if !ok {
			return 127, "", fmt.Errorf("unexpected git command: %s", key)
		}
		return result.exitCode, result.output, result.err
	}
}

func assertStringContains(t *testing.T, values []string, expected string) {
	t.Helper()
	for _, value := range values {
		if strings.Contains(value, expected) {
			return
		}
	}
	t.Fatalf("missing %q in %v", expected, values)
}

func TestRunReleaseRunRetriesWindowsGoTestCleanupLockOnce(t *testing.T) {
	previous := releaseRunExecuteCommand
	defer func() { releaseRunExecuteCommand = previous }()

	calls := []string{}
	releaseRunExecuteCommand = func(ctx context.Context, repoRoot, command string) (int, string, error) {
		calls = append(calls, command)
		switch len(calls) {
		case 1:
			if command != "go run ./cmd/rekit -- -Command release-check -Format json" {
				t.Fatalf("unexpected first command: %s", command)
			}
			return 0, "ok", nil
		case 2:
			if command != "go run ./cmd/rekit -- -Command status" {
				t.Fatalf("unexpected second command: %s", command)
			}
			return 0, "ok", nil
		case 3:
			if command != "go run ./cmd/rekit -- -Command packs" {
				t.Fatalf("unexpected third command: %s", command)
			}
			return 0, "ok", nil
		case 4:
			if command != "go run ./cmd/rekit -- -Command doctor" {
				t.Fatalf("unexpected fourth command: %s", command)
			}
			return 0, "ok", nil
		case 5:
			if command != "go test ./..." {
				t.Fatalf("unexpected fifth command: %s", command)
			}
			return 1, "ok after package tests\ngo: unlinkat C:\\Users\\13209\\AppData\\Local\\Temp\\go-build1234\\b001\\cli.test.exe: The process cannot access the file because it is being used by another process.", errors.New("exit status 1")
		case 6:
			if command != "go test ./..." {
				t.Fatalf("unexpected retry command: %s", command)
			}
			return 0, "ok after retry", nil
		case 7:
			if command != "go vet ./..." {
				t.Fatalf("unexpected seventh command: %s", command)
			}
			return 0, "ok", nil
		case 8:
			if command != "git diff --check" {
				t.Fatalf("unexpected eighth command: %s", command)
			}
			return 0, "ok", nil
		default:
			t.Fatalf("unexpected extra command %d: %s", len(calls), command)
			return 0, "", nil
		}
	}

	var out bytes.Buffer
	if err := Run([]string{"-Command", "release-run", "-Format", "json"}, &out); err != nil {
		t.Fatal(err)
	}
	var result releaseRunResult
	if err := json.Unmarshal(out.Bytes(), &result); err != nil {
		t.Fatalf("release-run JSON did not decode: %v\n%s", err, out.String())
	}
	if !result.Ready || result.Passed != 7 || result.Failed != 0 || result.Skipped != 0 || len(calls) != 8 {
		t.Fatalf("release-run retry result drifted: result=%+v calls=%+v", result, calls)
	}
	step := result.Steps[4]
	if step.Command != "go test ./..." || step.Status != "passed" || step.Attempts != 2 || step.FirstAttemptExitCode != 1 || step.FirstAttemptError != "exit status 1" || step.TransientRetryReason == "" || !strings.Contains(step.TransientRetryReason, "cleanup lock") || !strings.Contains(step.FirstAttemptOutputTail, "go: unlinkat") || step.Error != "" {
		t.Fatalf("release-run retry step drifted: %+v", step)
	}
	if result.Steps[5].Command != "go vet ./..." || result.Steps[6].Command != "git diff --check" {
		t.Fatalf("release-run retry reordered remaining commands: %+v", result.Steps)
	}
	var text bytes.Buffer
	if err := writeReleaseRunText(&text, result); err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(text.String(), "release-run step retry：index=5 attempts=2 firstExitCode=1 firstError=exit status 1 reason=windows go test temporary binary cleanup lock") || !strings.Contains(text.String(), "release-run step first attempt output tail：index=5 text=ok after package tests") {
		t.Fatalf("release-run retry text missing retry lines:\n%s", text.String())
	}
}

