func TestRunNoteAppendSupportsAllKinds(t *testing.T) {
	caseRoot := attachedCaseWithBoard(t)
	cases := []struct {
		kind  string
		path  string
		extra []string
	}{
		{kind: "observation", path: "observations.jsonl"},
		{kind: "hypothesis", path: "hypotheses.jsonl"},
		{kind: "candidate", path: "candidates.jsonl", extra: []string{"-Confidence", "medium"}},
		{kind: "verification", path: "verifications.jsonl", extra: []string{"-Verifier", "manual-review", "-Verdict", "inconclusive"}},
		{kind: "decision", path: "decisions.jsonl", extra: []string{"-Decision", "defer"}},
		{kind: "intervention", path: "interventions.jsonl", extra: []string{"-Action", "override", "-ApprovedBy", "lead"}},
		{kind: "rollback", path: "rollbacks.jsonl", extra: []string{"-TargetRef", "batch-one", "-Status", "resolved"}},
		{kind: "publication", path: "publications.jsonl"},
		{kind: "request", path: "requests.jsonl", extra: []string{"-Status", "pending-gate", "-Risk", "high"}},
	}
	for _, tc := range cases {
		t.Run(tc.kind, func(t *testing.T) {
			args := []string{"-Command", "note", "-Target", caseRoot, "-Pack", "_template", "-Kind", tc.kind, "-Lane", "main", "-Subject", tc.kind + " subject"}
			args = append(args, tc.extra...)
			var out bytes.Buffer
			if err := Run(args, &out); err != nil {
				t.Fatal(err)
			}
			var result struct {
				Applied bool   `json:"applied"`
				EventID string `json:"eventId"`
				Path    string `json:"path"`
				Event   struct {
					Kind string `json:"kind"`
				} `json:"event"`
			}
			if err := json.Unmarshal(out.Bytes(), &result); err != nil {
				t.Fatalf("note append stdout is not JSON: %v\n%s", err, out.String())
			}
			if !result.Applied || result.EventID == "" || result.Event.Kind != tc.kind || result.Path != ".rekit/facts/"+tc.path {
				t.Fatalf("unexpected note append result for %s: %+v", tc.kind, result)
			}
			ledger, err := os.ReadFile(filepath.Join(caseRoot, ".rekit", "facts", tc.path))
			if err != nil {
				t.Fatal(err)
			}
			if !strings.Contains(string(ledger), result.EventID) || !strings.Contains(string(ledger), `"kind":"`+tc.kind+`"`) {
				t.Fatalf("ledger missing %s event:\n%s", tc.kind, string(ledger))
			}
		})
	}
}

func TestRunNoteAppendWhatIfTextHandoffDoesNotWrite(t *testing.T) {
	caseRoot := attachedCaseWithBoard(t)
	before := snapshotFiles(t, filepath.Join(caseRoot, ".rekit"))
	var out bytes.Buffer
	if err := Run([]string{"-Command", "note", "-Target", caseRoot, "-Pack", "_template", "-Format", "text", "-WhatIf", "-Kind", "candidate", "-Lane", "main", "-Subject", "preview blocker", "-Confidence", "high", "-Status", "open"}, &out); err != nil {
		t.Fatal(err)
	}
	textOut := out.String()
	for _, expected := range []string{
		"note append：mutation=false applied=false reason=what-if eventId=",
		"path=.rekit/facts/candidates.jsonl kind=candidate lane=main subject=preview blocker",
		"note event：eventId=",
		"status=open",
		"confidence=high",
		"note mission brief：summary=",
		"note executor action：blocked=false ready=true",
		"note executor action commander action：state=ready-to-continue primary=`/rekit continue main`",
		"mission commander next action：state=ready-to-continue source=missionCommanderActions blocked=false requiresReview=false command=`/rekit continue main`",
		"note would executor action：blocked=true ready=false",
		"note would executor action requirements：reconcile=false pendingGate=false openDecision=true",
		"note would executor action commander action：state=needs-open-decision-review primary=`/rekit note -Kind decision -Lane main -Subject \"decision for candidate: preview blocker\" -Summary \"preview blocker\" -Decision <accept|reject|defer|supersede> -Reason \"reviewed open candidate/decision item\"",
		"note would mission commander next action：state=needs-open-decision-review source=missionCommanderActions blocked=false requiresReview=true command=`/rekit note -Kind decision -Lane main -Subject \"decision for candidate: preview blocker\" -Summary \"preview blocker\" -Decision <accept|reject|defer|supersede> -Reason \"reviewed open candidate/decision item\"",
		"note would mission commander next action：state=needs-open-decision-review source=missionCommanderActions.followUp blocked=true requiresReview=true command=`/rekit continue main -WhatIf`",
		"note would mission commander next action：state=needs-open-decision-review source=missionCommanderActions.followUp blocked=true requiresReview=true command=`/rekit handoff main`",
	} {
		if !strings.Contains(textOut, expected) {
			t.Fatalf("note what-if text missing %q:\n%s", expected, textOut)
		}
	}
	if strings.Contains(textOut, "{\n  ") {
		t.Fatalf("note what-if text should not emit JSON object:\n%s", textOut)
	}
	after := snapshotFiles(t, filepath.Join(caseRoot, ".rekit"))
	assertSnapshotEqual(t, before, after)
}

func TestRunNoteAppendWhatIfDoesNotWrite(t *testing.T) {
	caseRoot := attachedCaseWithBoard(t)
	before := snapshotFiles(t, filepath.Join(caseRoot, ".rekit"))
	var out bytes.Buffer
	if err := Run([]string{"-Command", "note", "-Target", caseRoot, "-Pack", "_template", "-WhatIf", "-Kind", "candidate", "-Lane", "main", "-Subject", "preview blocker", "-Confidence", "high", "-Status", "open"}, &out); err != nil {
		t.Fatal(err)
	}
	var result struct {
		IsMutation                       bool                             `json:"isMutation"`
		Applied                          bool                             `json:"applied"`
		Reason                           string                           `json:"reason"`
		Path                             string                           `json:"path"`
		EventSHA256                      string                           `json:"eventSha256"`
		RecordCommand                    string                           `json:"recordCommand"`
		Event                            map[string]any                   `json:"event"`
		MissionBrief                     missionBrief                     `json:"missionBrief"`
		ExecutorAction                   executorActionSnapshot           `json:"executorAction"`
		MissionCommanderAction           missionCommanderActionSnapshot   `json:"missionCommanderAction"`
		MissionCommanderNextActions      []missionCommanderNextActionItem `json:"missionCommanderNextActions"`
		WouldExecutorAction              executorActionSnapshot           `json:"wouldExecutorAction"`
		WouldMissionCommanderAction      missionCommanderActionSnapshot   `json:"wouldMissionCommanderAction"`
		WouldMissionCommanderNextActions []missionCommanderNextActionItem `json:"wouldMissionCommanderNextActions"`
	}
	if err := json.Unmarshal(out.Bytes(), &result); err != nil {
		t.Fatalf("note what-if stdout is not JSON: %v\n%s", err, out.String())
	}
	if result.IsMutation || result.Applied || result.Reason != "what-if" || result.Path != ".rekit/facts/candidates.jsonl" || len(result.EventSHA256) != 64 || !strings.Contains(result.RecordCommand, "-ExpectedNoteEventSha256 "+result.EventSHA256) || !strings.Contains(result.RecordCommand, "-CreatedAt ") || !strings.Contains(result.RecordCommand, "-EventId ") {
		t.Fatalf("unexpected note what-if result: %+v", result)
	}
	if result.MissionBrief.Summary == "" || result.ExecutorAction.Blocked || !result.ExecutorAction.Ready || !result.WouldExecutorAction.Blocked || result.WouldExecutorAction.Ready || result.WouldExecutorAction.OpenDecisions != 1 || !result.WouldExecutorAction.OpenDecisionRequired {
		t.Fatalf("unexpected note current/would actions: %+v", result)
	}
	if result.MissionCommanderAction.State != "ready-to-continue" || result.WouldMissionCommanderAction.State != "needs-open-decision-review" {
		t.Fatalf("note what-if should expose current/would commander action delta: current=%+v would=%+v", result.MissionCommanderAction, result.WouldMissionCommanderAction)
	}
	wouldPreviewCommand := result.WouldMissionCommanderAction.PrimaryCommand
	if !containsMissionCommanderNextAction(result.MissionCommanderNextActions, "missionCommanderActions", "/rekit continue main", false, false) || !strings.HasPrefix(wouldPreviewCommand, "/rekit note -Kind decision -Lane main") || !strings.Contains(wouldPreviewCommand, "-Related "+result.Event["eventId"].(string)) || !containsMissionCommanderNextAction(result.WouldMissionCommanderNextActions, "missionCommanderActions", wouldPreviewCommand, false, true) || !containsMissionCommanderNextAction(result.WouldMissionCommanderNextActions, "missionCommanderActions.followUp", "/rekit continue main -WhatIf", true, true) || !containsMissionCommanderNextAction(result.WouldMissionCommanderNextActions, "missionCommanderActions.followUp", "/rekit handoff main", true, true) {
		t.Fatalf("note what-if commander next actions drifted: current=%+v would=%+v", result.MissionCommanderNextActions, result.WouldMissionCommanderNextActions)
	}
	after := snapshotFiles(t, filepath.Join(caseRoot, ".rekit"))
	assertSnapshotEqual(t, before, after)
}

func TestRunNoteHashBoundRecordRejectsDrift(t *testing.T) {
	caseRoot := attachedCaseWithBoard(t)
	before := snapshotFiles(t, filepath.Join(caseRoot, ".rekit"))
	var preview bytes.Buffer
	if err := Run([]string{"-Command", "note", "-Target", caseRoot, "-Pack", "_template", "-WhatIf", "-Kind", "decision", "-Lane", "main", "-Subject", "decision for preview", "-Summary", "accept preview candidate", "-Decision", "accept", "-Reason", "reviewed evidence", "-Related", "cand-hash-bound", "-EventId", "dec-hash-bound", "-CreatedAt", "2026-07-25T10:20:00Z"}, &preview); err != nil {
		t.Fatal(err)
	}
	var plan struct {
		Applied       bool           `json:"applied"`
		Reason        string         `json:"reason"`
		EventSHA256   string         `json:"eventSha256"`
		RecordCommand string         `json:"recordCommand"`
		Event         map[string]any `json:"event"`
	}
	if err := json.Unmarshal(preview.Bytes(), &plan); err != nil {
		t.Fatalf("note hash-bound preview stdout is not JSON: %v\n%s", err, preview.String())
	}
	if plan.Applied || plan.Reason != "what-if" || len(plan.EventSHA256) != 64 || !strings.Contains(plan.RecordCommand, "-ExpectedNoteEventSha256 "+plan.EventSHA256) || plan.Event["createdAt"] != "2026-07-25T10:20:00Z" || plan.Event["eventId"] != "dec-hash-bound" {
		t.Fatalf("unexpected hash-bound preview: %+v", plan)
	}
	afterPreview := snapshotFiles(t, filepath.Join(caseRoot, ".rekit"))
	assertSnapshotEqual(t, before, afterPreview)

	var drift bytes.Buffer
	driftArgs := []string{"-Command", "note", "-Target", caseRoot, "-Pack", "_template", "-Kind", "decision", "-Lane", "main", "-Subject", "decision for preview", "-Summary", "accept preview candidate", "-Decision", "reject", "-Reason", "reviewed evidence", "-Related", "cand-hash-bound", "-EventId", "dec-hash-bound", "-CreatedAt", "2026-07-25T10:20:00Z", "-ExpectedNoteEventSha256", plan.EventSHA256}
	err := Run(driftArgs, &drift)
	if err == nil || !strings.Contains(err.Error(), "note event sha256 changed after preview") {
		t.Fatalf("drift error = %v, stdout=%s", err, drift.String())
	}
	afterDrift := snapshotFiles(t, filepath.Join(caseRoot, ".rekit"))
	assertSnapshotEqual(t, before, afterDrift)

	var applied bytes.Buffer
	applyArgs := []string{"-Command", "note", "-Target", caseRoot, "-Pack", "_template", "-Kind", "decision", "-Lane", "main", "-Subject", "decision for preview", "-Summary", "accept preview candidate", "-Decision", "accept", "-Reason", "reviewed evidence", "-Related", "cand-hash-bound", "-EventId", "dec-hash-bound", "-CreatedAt", "2026-07-25T10:20:00Z", "-ExpectedNoteEventSha256", plan.EventSHA256}
	if err := Run(applyArgs, &applied); err != nil {
		t.Fatal(err)
	}
	var result struct {
		Applied             bool           `json:"applied"`
		EventSHA256         string         `json:"eventSha256"`
		ExpectedEventSHA256 string         `json:"expectedEventSha256"`
		Event               map[string]any `json:"event"`
	}
	if err := json.Unmarshal(applied.Bytes(), &result); err != nil {
		t.Fatalf("note hash-bound apply stdout is not JSON: %v\n%s", err, applied.String())
	}
	if !result.Applied || result.EventSHA256 != plan.EventSHA256 || result.ExpectedEventSHA256 != plan.EventSHA256 || result.Event["decision"] != "accept" || result.Event["createdAt"] != "2026-07-25T10:20:00Z" {
		t.Fatalf("unexpected hash-bound apply: %+v", result)
	}
	ledger, err := os.ReadFile(filepath.Join(caseRoot, ".rekit", "facts", "decisions.jsonl"))
	if err != nil {
		t.Fatal(err)
	}
	text := string(ledger)
	if !strings.Contains(text, `"eventId":"dec-hash-bound"`) || !strings.Contains(text, `"decision":"accept"`) || strings.Contains(text, `"decision":"reject"`) {
		t.Fatalf("hash-bound ledger drifted:\n%s", text)
	}
}

