func assertExecutionEvidenceAdapterContextSnapshot(t *testing.T, label string, candidate *adapterToolCandidateSnapshot, wantID string) {
	t.Helper()
	if candidate == nil || candidate.ID != wantID || candidate.Status != "cautious" || !strings.Contains(candidate.Entry, "dynamic-debug") || !strings.Contains(candidate.Purpose, "bounded debug") || !containsSubstring(candidate.SideEffects, "process execution") || !slices.Contains(candidate.GateActions, "debug") || candidate.ToolingCatalogPath != "tooling/catalog.yml" || !containsSubstring(candidate.ReportGuidance, "adapterId") || !containsSubstring(candidate.EvidenceGuidance, "ValidateArgs") || strings.Join(candidate.StopConditionHints, ",") != "timeout,unexpected-side-effect,scope-drift" || !candidate.RecordOnlyAfterGate {
		t.Fatalf("%s omitted execution evidence adapter context detail: %+v", label, candidate)
	}
}

func assertAuthorizedGateAdapterHandoffSnapshot(t *testing.T, label string, items []authorizedGateAdapterHandoffSnapshot, eventID, wantContract string) {
	t.Helper()
	wantReportPath := "workspace/main/debug/session-1/adapter-report.json"
	if len(items) != 1 {
		t.Fatalf("%s authorized gate adapter handoff count = %d, want 1: %+v", label, len(items), items)
	}
	item := items[0]
	if item.EventID != eventID || item.Lane != "main" || item.Subject != "authorized debug" || item.Action != "debug" || item.Target != "target-alpha" || item.Status != "authorized-gate" || item.Authorization != "preauthorized" || item.Profile != "prof-main-debug" || item.ReportContract != wantContract || item.DefaultReportPath != wantReportPath || item.ReportPath != wantReportPath || item.HandoffCommand != "/rekit handoff main" {
		t.Fatalf("%s authorized gate adapter handoff identity drifted: %+v", label, item)
	}
	if item.ReportSummary == nil || item.ReportSummary.ReportPath != wantReportPath || item.ReportSummary.DefaultReportPath != wantReportPath || item.ReportSummary.AllowedStatusCount != 5 || item.ReportSummary.AllowedOutputPathCount != 1 || item.ReportSummary.AuthorizedStopCount != 1 || item.ReportSummary.OutcomeCount == 0 {
		t.Fatalf("%s authorized gate adapter handoff missing compact report summary: %+v", label, item.ReportSummary)
	}
	if item.LiveValidation == nil || item.LiveValidation.ReportFileName != "adapter-report.json" || item.LiveValidation.CaseRelativeReportPath != wantReportPath || item.LiveValidation.AdapterCandidateCount != 0 || item.LiveValidation.SidecarTemplateAdapterID != "<adapter-id>" || !strings.Contains(item.LiveValidation.CaseRelativeValidateCommand, wantReportPath) || item.LiveValidation.RecordCommand != "" || item.LiveValidation.CaseRelativeRecordCommand != "" {
		t.Fatalf("%s authorized gate adapter handoff should expose validation-only pre-validation handoff: %+v", label, item.LiveValidation)
	}
	if item.LiveValidation.DispatchCommand == "" || item.LiveValidation.CurrentRunLoopStepID != "draft-or-write-report" || len(item.LiveValidation.RunLoop) < 6 || item.LiveValidation.RunLoop[0].StepID != "inspect-contract" || item.LiveValidation.RunLoop[len(item.LiveValidation.RunLoop)-1].StepID != "review-recorded-evidence" {
		t.Fatalf("%s authorized gate adapter handoff missing ordered live validation run loop: %+v", label, item.LiveValidation)
	}
	if !containsSubstring(item.LiveValidation.AuthorizedWorkspaces, "workspace/main/debug/session-1") || !containsSubstring(item.Evidence, "authorized outputPaths workspace/main/debug/session-1") || !containsSubstring(item.Evidence, "authorized stopConditions timeout") || !containsSubstring(item.Boundary, "projection may read and validate an existing canonical sidecar") || !containsSubstring(item.Boundary, "no heavy-tool replay") {
		t.Fatalf("%s authorized gate adapter handoff missing workspace/evidence/boundary: %+v", label, item)
	}
	if !containsSubstring(item.LiveValidation.RunbookSteps, "confirm authorized output workspace and adapter-report.json sidecar path before adapter work") || !containsSubstring(item.LiveValidation.RunbookSteps, "record command is intentionally unavailable until validation/status returns valid=true with -ExpectedExecutionReportSha256") {
		t.Fatalf("%s authorized gate adapter handoff missing live validation runbook: %+v", label, item.LiveValidation)
	}
}

func assertAcknowledgedAuthorizedGateAdapterHandoffSnapshot(t *testing.T, label string, item authorizedGateAdapterHandoffSnapshot, eventID string) {
	t.Helper()
	if item.EventID != eventID || !item.Acknowledged || item.AcknowledgementState != "execution-evidence-review-acknowledged" {
		t.Fatalf("%s authorized gate adapter handoff missing acknowledgement closure: %+v", label, item)
	}
	if item.ReportSummary == nil || item.ReportSummary.State != "evidence-already-recorded" || item.ReportSummary.CurrentAction != "" || item.ReportSummary.NextActionCount != 0 || item.ReportSummary.ReviewRequiredActionCount != 0 || item.ReportSummary.ActionQueueSummary != "" || !containsSubstring(item.ReportSummary.Boundary, "execution evidence review is acknowledged/closed") {
		t.Fatalf("%s authorized gate adapter handoff retained current review action after acknowledgement: %+v", label, item.ReportSummary)
	}
	if item.LiveValidation == nil || item.LiveValidation.RecordCommand != "" || item.LiveValidation.CaseRelativeRecordCommand != "" || !strings.Contains(item.LiveValidation.ReplayBehavior, "acknowledged recorded evidence is closed") {
		t.Fatalf("%s authorized gate adapter handoff retained live record action after acknowledgement: %+v", label, item.LiveValidation)
	}
	if !containsSubstring(item.Evidence, "execution evidence review acknowledged for gateEventId "+eventID) || !containsSubstring(item.Boundary, "acknowledged recorded adapter evidence is retained as provenance only") {
		t.Fatalf("%s authorized gate adapter handoff omitted provenance-only acknowledgement evidence/boundary: %+v", label, item)
	}
}

